t.script:
(function(){
  var EV=[
    {t:'The Body in the Room',s:'Online &middot; 25 Nov 2026 &middot; 7&#8211;9pm SGT',img:'card-event-body-in-the-room.webp?v=1',h:'/event-body-in-the-room',end:'2026-11-25'},
    {t:'Breath as a medicine',s:'Online &middot; 15 Dec 2026 &middot; 7&#8211;9pm SGT',img:'card-event-breath-as-medicine.webp?v=1',h:'/event-breath-as-medicine',end:'2026-12-15'},
    {t:'The Art of Conscious Rest',s:'Online &middot; 24 Jan 2027 &middot; 8&#8211;10pm SGT',img:'card-event-art-of-conscious-rest.webp?v=1',h:'/event-art-of-conscious-rest',end:'2027-01-24'},
    {t:'TRE&#8482; Module 1 &mdash; Lisbon',s:'Lisboa &middot; 28&#8211;30 May 2027',img:'card-event-lisbon-module1.webp?v=2',h:'/event-tre-module1-lisbon',end:'2027-05-30'},
    {t:'TRE&#8482; Certification &mdash; Lisboa 2027',s:'Lisboa &middot; Modules 1&#8211;3 &middot; May&#8211;Oct 2027',img:'event-lisbon-certification.webp?v=2',h:'/event-tre-certification-lisbon',end:'2027-10-24'},
    {t:'TRE&#8482; Module 1 ONLINE &mdash; TRE Scotland',s:'Online &middot; 18&#8211;20 June 2027 &middot; UK time',img:'card-event-scotland-online-module1.webp?v=2',h:'/event-tre-module1-online-scotland',end:'2027-06-20'}
  ];
  var now=Date.now(), grid=document.getElementById('ce-more-grid'), empty=document.getElementById('ce-more-empty');
  var live=EV.filter(function(e){ return Date.parse(e.end+'T23:59:59+08:00')>now; }).slice(0,3);
  if(!live.length){ grid.style.display='none'; empty.hidden=false; return; }
  grid.innerHTML=live.map(function(e){ return '<a class="ce-rel" href="'+e.h+'"><img src="images/'+e.img+'" alt="" loading="lazy" decoding="async" /><div class="b"><strong>'+e.t+'</strong><span>'+e.s+'</span></div></a>'; }).join('');
})();

(function(){
  var poster=document.getElementById('ce-poster'), lb=document.getElementById('ce-lightbox'),
      close=document.getElementById('ce-lightbox-close');
  if(!poster||!lb) return;
  function open(){ lb.classList.add('open'); lb.setAttribute('aria-hidden','false'); document.body.style.overflow='hidden'; }
  function shut(){ lb.classList.remove('open'); lb.setAttribute('aria-hidden','true'); document.body.style.overflow=''; }
  poster.addEventListener('click', open);
  poster.addEventListener('keydown', function(e){ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); open(); } });
  lb.addEventListener('click', function(e){ if(e.target===lb||e.target===close) shut(); });
  document.addEventListener('keydown', function(e){ if(e.key==='Escape') shut(); });
})();

function evtlSubmit(e) {
  e.preventDefault();
  var fd = new FormData(e.target);
  sendLead({
    name: fd.get('name') || '',
    email: fd.get('email') || '',
    phone: fd.get('phone') || '',
    event: fd.get('event') || '',
    inquiry: 'Event registration enquiry',
    source: fd.get('source') || document.title,
    message: 'Payment plan: ' + (fd.get('payment_plan') || '') + (fd.get('message') ? ' | ' + fd.get('message') : ''),
    payment_plan: fd.get('payment_plan') || ''
  });
  var card = e.target.closest('.evtl-form-card');
  card.querySelector('.evtl-form').style.display = 'none';
  var s = card.querySelector('.evtl-form-success');
  s.style.display = 'block';
}
